"use strict";(globalThis.webpackChunkp_vs_np_docs=globalThis.webpackChunkp_vs_np_docs||[]).push([[4258],{49213(e){e.exports=JSON.parse('{"tag":{"label":"np-hard","permalink":"/azeon/p-vs-np/tags/np-hard","allTagsPath":"/azeon/p-vs-np/tags","count":3,"items":[{"id":"real-world-impact/computational-biology","title":"Computational Biology","description":"A protein is a chain that folds itself into a precise 3D shape, and the shape decides what it does. Simplified versions of predicting that shape are NP-Hard. Then, in 2020, AlphaFold started getting real shapes right, and won a Nobel Prize.","permalink":"/azeon/p-vs-np/real-world-impact/computational-biology"},{"id":"real-world-impact/machine-learning-constraints","title":"Machine Learning Constraints","description":"Training even a tiny neural network perfectly is NP-Hard. Yet machine learning works astonishingly well. The reason is the same lesson again: training never asks for the perfect answer, and real data isn\'t the worst case.","permalink":"/azeon/p-vs-np/real-world-impact/machine-learning-constraints"},{"id":"complexity-zoo/np-hard-vs-np-complete","title":"NP-Hard vs. NP-Complete","description":"Two labels I\'d been using almost interchangeably. NP-Complete means \'hardest inside NP\'. NP-Hard only means \'at least that hard\', and some NP-Hard problems can\'t be solved by any computer, ever.","permalink":"/azeon/p-vs-np/complexity-zoo/np-hard-vs-np-complete"}],"unlisted":false}}')}}]);